import math


def _apply_op(op: str, values: list[int]) -> None:
    if op == "u-":
        if not values:
            raise ValueError("Missing operand for unary minus")
        values[-1] = -values[-1]
        return

    if len(values) < 2:
        raise ValueError(f"Missing operand for operator {op!r}")

    b = values.pop()
    a = values.pop()

    if op == "+":
        values.append(a + b)
    elif op == "-":
        values.append(a - b)
    elif op == "*":
        values.append(a * b)
    elif op == "/":
        if b == 0:
            raise ValueError("Division by zero")
        q = abs(a) // abs(b)
        values.append(-q if (a < 0) ^ (b < 0) else q)
    elif op == "%":
        if b == 0:
            raise ValueError("Remainder by zero")
        r = abs(a) % abs(b)
        values.append(-r if a < 0 else r)
    elif op == "^":
        if b < 0:
            raise ValueError("Negative exponent")
        values.append(a**b)
    else:
        raise ValueError(f"Unknown operator {op!r}")


def _parse_int(tok: str) -> int:
    if len(tok) <= 4000:
        return int(tok)
    val = 0
    for k in range(0, len(tok), 4000):
        chunk = tok[k : k + 4000]
        val = val * (10 ** len(chunk)) + int(chunk)
    return val


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    tokens: list[str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in "+-*/%^!()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    prec = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
        "%": 2,
        "u-": 3,
        "^": 4,
    }

    values: list[int] = []
    ops: list[str] = []
    expect_operand = True

    for tok in tokens:
        if expect_operand:
            if "0" <= tok[0] <= "9":
                values.append(_parse_int(tok))
                expect_operand = False
            elif tok == "(":
                ops.append("(")
            elif tok == "-":
                ops.append("u-")
            else:
                raise ValueError(f"Unexpected token {tok!r}")
        else:
            if tok == "!":
                if not values:
                    raise ValueError("Missing operand for factorial")
                v = values.pop()
                if v < 0:
                    raise ValueError("Factorial of negative number")
                values.append(math.factorial(v))
            elif tok == ")":
                while ops and ops[-1] != "(":
                    _apply_op(ops.pop(), values)
                if not ops or ops[-1] != "(":
                    raise ValueError("Mismatched parentheses")
                ops.pop()
            elif tok == "(":
                # Implicit multiplication after a number, ')' or '!'
                while ops and ops[-1] != "(" and prec[ops[-1]] >= prec["*"]:
                    _apply_op(ops.pop(), values)
                ops.append("*")
                ops.append("(")
                expect_operand = True
            elif tok in ("+", "-", "*", "/", "%", "^"):
                if tok == "^":
                    while ops and ops[-1] != "(" and prec[ops[-1]] > prec[tok]:
                        _apply_op(ops.pop(), values)
                else:
                    while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[tok]:
                        _apply_op(ops.pop(), values)
                ops.append(tok)
                expect_operand = True
            else:
                raise ValueError(f"Unexpected token {tok!r}")

    if expect_operand:
        raise ValueError("Incomplete expression")

    while ops:
        op = ops.pop()
        if op == "(":
            raise ValueError("Mismatched parentheses")
        _apply_op(op, values)

    if len(values) != 1:
        raise ValueError("Malformed expression")

    return values[0]
